import{_ as a,q as s,z as i,V as p}from"./chunks/framework.OtifAeFI.js";const e=JSON.parse('{"title":"保姆级搭建OpenWebUI教程","description":"OpenWebUI的详细教程","frontmatter":{"title":"保姆级搭建OpenWebUI教程","tags":["AI"],"categories":["OpenWebUI"],"date":"2025-01-19T00:00:00.000Z","description":"OpenWebUI的详细教程","articleGPT":"本文详细介绍了如何利用雨云服务器，通过Docker或Python安装Open WebUI并结合第三方API快速搭建个人AI应用，涵盖服务器选择、环境配置及API对接等关键步骤。","head":[["link",{"rel":"canonical","href":"https://www.696898.xyz/posts/2025/0119"}]]},"headers":[],"relativePath":"posts/2025/0119.md","filePath":"posts/2025/0119.md","lastUpdated":1741095097000}');const n=a({name:"posts/2025/0119.md"},[["render",function(a,e,n,t,g,l){return i(),s("div",null,e[0]||(e[0]=[p('<h2 id="服务器" tabindex="-1">服务器 <a class="header-anchor" href="#服务器" aria-label="Permalink to &quot;服务器&quot;">​</a></h2><p>这里推荐使用 <strong>雨云</strong> 服务器。点击以下链接注册可获得首月五折优惠卷 <a href="https://www.rainyun.com/Koishi_" target="_blank" rel="noreferrer">雨云注册链接</a>。</p><p>同时这里建议购买 <strong>香港 美国</strong> 地区服务器，域名无需备案。</p><p><a class="img-fancybox" href="/public/images/pages/0119/image.png" data-fancybox="gallery" data-caption="地区选择"><img class="post-img" src="/assets/image.D0KH5PIy.png" alt="地区选择" loading="lazy"><span class="post-img-tip">地区选择</span></a></p><p>地区选择</p><p>配置请选择配置大于等于 <strong>2C2G</strong> 的机器，不推荐使用低于 <strong>2G</strong> 内存机器</p><p><a class="img-fancybox" href="/public/images/pages/0119/image1.png" data-fancybox="gallery" data-caption="配置选择"><img class="post-img" src="/assets/image1.d2uTDi_H.png" alt="配置选择" loading="lazy"><span class="post-img-tip">配置选择</span></a></p><p>配置选择</p><p>选择系统时请务必选择 <strong>Debian 12</strong> 系统并预装 <strong>1Panel</strong> 面板</p><p><a class="img-fancybox" href="/public/images/pages/0119/image2.png" data-fancybox="gallery" data-caption="系统选择"><img class="post-img" src="/assets/image2.DkleSnPj.png" alt="系统选择" loading="lazy"><span class="post-img-tip">系统选择</span></a></p><p>系统选择</p><h2 id="ssh-客户端-本项目为可选" tabindex="-1">SSH 客户端（本项目为可选） <a class="header-anchor" href="#ssh-客户端-本项目为可选" aria-label="Permalink to &quot;SSH 客户端（本项目为可选）&quot;">​</a></h2><p>这里我个人使用 <strong>Termius</strong> 作为 SSH 客户端，你可以点击 <a href="https://termius.com/free-ssh-client-for-windows" target="_blank" rel="noreferrer">Free SSH Client for Windows</a> 官网下载。</p><p><a class="img-fancybox" href="/public/images/pages/0119/image3.png" data-fancybox="gallery" data-caption="Termius"><img class="post-img" src="/assets/image3.BPx16_s-.png" alt="Termius" loading="lazy"><span class="post-img-tip">Termius</span></a></p><p>Termius</p><p>如果你认为 <strong>Termius</strong> 没有中文，且太过复杂。你可以使用 <strong>Xshell</strong> 作为 SSH 客户端，你可以前往 <a href="https://www.xshell.com/zh/free-for-home-school/" target="_blank" rel="noreferrer">家庭/学校免费 - NetSarang Website</a> 官网下载。</p><p><a class="img-fancybox" href="/public/images/pages/0119/image4.png" data-fancybox="gallery" data-caption="Xshell"><img class="post-img" src="/assets/image4.B5vn03pf.png" alt="Xshell" loading="lazy"><span class="post-img-tip">Xshell</span></a></p><p>Xshell</p><p>以上两个软件均有 <strong>免费</strong> 计划/版本，根据自身需求选用。</p><h3 id="连接示例" tabindex="-1">连接示例 <a class="header-anchor" href="#连接示例" aria-label="Permalink to &quot;连接示例&quot;">​</a></h3><p><a class="img-fancybox" href="/public/images/pages/0119/image5.png" data-fancybox="gallery" data-caption="相关信息"><img class="post-img" src="/assets/image5.FzGdiFLD.png" alt="相关信息" loading="lazy"><span class="post-img-tip">相关信息</span></a></p><p>相关信息</p><p><a class="img-fancybox" href="/public/images/pages/0119/image6.png" data-fancybox="gallery" data-caption="添加连接"><img class="post-img" src="/assets/image6.Bv-aNNR7.png" alt="添加连接" loading="lazy"><span class="post-img-tip">添加连接</span></a></p><p>添加连接</p><p><a class="img-fancybox" href="/public/images/pages/0119/image7.png" data-fancybox="gallery" data-caption="保存密钥"><img class="post-img" src="/assets/image7.CIX0Scil.png" alt="保存密钥" loading="lazy"><span class="post-img-tip">保存密钥</span></a></p><p>保存密钥</p><p><a class="img-fancybox" href="/public/images/pages/0119/image8.png" data-fancybox="gallery" data-caption="输入用户名"><img class="post-img" src="/assets/image8.CyGk21Dy.png" alt="输入用户名" loading="lazy"><span class="post-img-tip">输入用户名</span></a></p><p>输入用户名</p><p><a class="img-fancybox" href="/public/images/pages/0119/image9.png" data-fancybox="gallery" data-caption="输入密码"><img class="post-img" src="/assets/image9.Df1Eie7Q.png" alt="输入密码" loading="lazy"><span class="post-img-tip">输入密码</span></a></p><p>输入密码</p><h2 id="访问面板" tabindex="-1">访问面板 <a class="header-anchor" href="#访问面板" aria-label="Permalink to &quot;访问面板&quot;">​</a></h2><p>如果你选择 <strong>预装</strong>了 <strong>1Panel</strong> 面板，你可以看到以下信息</p><p><a class="img-fancybox" href="/public/images/pages/0119/image10.png" data-fancybox="gallery" data-caption="image.png"><img class="post-img" src="/assets/image10.B-7byDX0.png" alt="image.png" loading="lazy"><span class="post-img-tip">image.png</span></a></p><p>将地址输入到 <strong>浏览器地址栏</strong> 即可访问</p><h2 id="安装open-webui" tabindex="-1">安装Open WebUI <a class="header-anchor" href="#安装open-webui" aria-label="Permalink to &quot;安装Open WebUI&quot;">​</a></h2><h3 id="python-pip安装" tabindex="-1">Python pip安装 <a class="header-anchor" href="#python-pip安装" aria-label="Permalink to &quot;Python pip安装&quot;">​</a></h3><p>打开面板 依次找到 <strong>网站</strong> &gt; <strong>运行环境</strong> &gt; <strong>Python</strong></p><p><a class="img-fancybox" href="/public/images/pages/0119/image11.png" data-fancybox="gallery" data-caption="新建一个运行环境"><img class="post-img" src="/assets/image11.BeZ491Kb.png" alt="新建一个运行环境" loading="lazy"><span class="post-img-tip">新建一个运行环境</span></a></p><p>新建一个运行环境</p><p>输入命令为<code>pip install open-webui &amp;&amp; open-webui serve</code> 其余按照以下图示填写</p><p><a class="img-fancybox" href="/public/images/pages/0119/image12.png" data-fancybox="gallery" data-caption="输入相关参数"><img class="post-img" src="/assets/image12.D3-c1zJH.png" alt="输入相关参数" loading="lazy"><span class="post-img-tip">输入相关参数</span></a></p><p>输入相关参数</p><p>然后就是 等待 等待 等待</p><h3 id="docker-安装-推荐" tabindex="-1">Docker 安装（推荐） <a class="header-anchor" href="#docker-安装-推荐" aria-label="Permalink to &quot;Docker 安装（推荐）&quot;">​</a></h3><p>在 <strong>SSH 客户端</strong> 中输入以下命令</p><div class="language-jsx vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">OPENAI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your_secret_key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v open</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">webui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name open</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webui </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">restart always ghcr.io</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">open</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webui</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">open</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">webui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:main</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>等待即可</p><h2 id="配置open-webui" tabindex="-1">配置Open WebUI <a class="header-anchor" href="#配置open-webui" aria-label="Permalink to &quot;配置Open WebUI&quot;">​</a></h2><p>访问<a href="http://xn--IP-xz4cu2tkcs091a:8080" target="_blank" rel="noreferrer"><code>http://公网IP地址:8080</code></a> (Python pip安装）Or <a href="http://xn--IP-xz4cu2tkcs091a:3000" target="_blank" rel="noreferrer"><code>http://公网IP地址:3000</code></a>(Docker 安装）即可访问。</p><p>根据指引初始化 <strong>管理员账户</strong> ，初始化之后为以下界面：</p><p><a class="img-fancybox" href="/public/images/pages/0119/image13.png" data-fancybox="gallery" data-caption="image.png"><img class="post-img" src="/assets/image13.meTwSFZQ.png" alt="image.png" loading="lazy"><span class="post-img-tip">image.png</span></a></p><p>现在并不能使用大模型，它依赖于API，我们现在就要配置API</p><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><p>这里我们使用 <a href="https://vip.bili2233.work" target="_blank" rel="noreferrer">https://vip.bili2233.work</a> 作为 API 提供商，当然你也可以使用 OpenAI、Claude、Gemini官方API，但是可能需要海外手机号并且Gemini限制地区。</p><p>访问 <a href="https://vip.bili2233.work/" target="_blank" rel="noreferrer">https://vip.bili2233.work</a> 并注册账号</p><p><a class="img-fancybox" href="/public/images/pages/0119/image14.png" data-fancybox="gallery" data-caption="image.png"><img class="post-img" src="/assets/image14.C-nFfm3j.png" alt="image.png" loading="lazy"><span class="post-img-tip">image.png</span></a></p><p>将令牌复制并保存</p><p><a class="img-fancybox" href="/public/images/pages/0119/image15.png" data-fancybox="gallery" data-caption="image.png"><img class="post-img" src="/assets/image15.CW-9A8V5.png" alt="image.png" loading="lazy"><span class="post-img-tip">image.png</span></a></p><p>依次点击 <strong>头像</strong> &gt; <strong>管理员面板</strong> 进入设置</p><p><a class="img-fancybox" href="/public/images/pages/0119/image16.png" data-fancybox="gallery" data-caption="image.png"><img class="post-img" src="/assets/image16.DYlI5_Rg.png" alt="image.png" loading="lazy"><span class="post-img-tip">image.png</span></a></p><p>找到外部连接</p><p><a class="img-fancybox" href="/public/images/pages/0119/image17.png" data-fancybox="gallery" data-caption="image.png"><img class="post-img" src="/assets/image17.D3laGghP.png" alt="image.png" loading="lazy"><span class="post-img-tip">image.png</span></a></p><p>随即将 <code>https://vip.openai.com/v1</code> 改为 <code>[https://vip.bili2233.work/v1](https://vip.bili2233.work/v1)</code> 并且 密钥填为刚刚复制的令牌。</p><p><a class="img-fancybox" href="/public/images/pages/0119/image18.png" data-fancybox="gallery" data-caption="image.png"><img class="post-img" src="/assets/image18.S9eir9oU.png" alt="image.png" loading="lazy"><span class="post-img-tip">image.png</span></a></p><p>回到首页即可选择模型并对话</p><p><a class="img-fancybox" href="/public/images/pages/0119/image19.png" data-fancybox="gallery" data-caption="image.png"><img class="post-img" src="/assets/image19.2rr-pSoC.png" alt="image.png" loading="lazy"><span class="post-img-tip">image.png</span></a></p>',66)]))}]]);export{e as __pageData,n as default};
